namespace InventoryApp.Models;

public class EquipmentItem
{
    public int Id { get; set; }
    public string Name { get; set; } = string.Empty;
    public string Location { get; set; } = string.Empty;
    public DateTime LastInspected { get; set; }
}

using InventoryApp.Models;

namespace InventoryApp.Services;

public class EquipmentService
{
    public async Task<List<EquipmentItem>> GetEquipmentAsync()
    {
        // Simulate a slow data source so the loading state is visible.
        await Task.Delay(500);

        return new List<EquipmentItem>
        {
            new() { Id = 1, Name = "Hydraulic Press",     Location = "Building A",  LastInspected = new DateTime(2026, 5, 10) },
            new() { Id = 2, Name = "CNC Lathe",           Location = "Building B",  LastInspected = new DateTime(2026, 4, 22) },
            new() { Id = 3, Name = "Forklift #7",         Location = "Warehouse C", LastInspected = new DateTime(2026, 6, 1) },
            new() { Id = 4, Name = "Conveyor Belt Motor", Location = "Building A",  LastInspected = new DateTime(2026, 3, 15) },
            new() { Id = 5, Name = "Welding Robot Arm",   Location = "Building D",  LastInspected = new DateTime(2026, 6, 18) },
            new() { Id = 6, Name = "Air Compressor",      Location = "Utility Shed", LastInspected = new DateTime(2026, 2, 28) },
            new() { Id = 7, Name = "Overhead Crane",      Location = "Building B",  LastInspected = new DateTime(2026, 5, 30) },
            new() { Id = 8, Name = "Band Saw",            Location = "Workshop",    LastInspected = new DateTime(2026, 1, 12) },
        };
    }
}

@page "/inventory"
@rendermode InteractiveServer
@implements IDisposable
@inject EquipmentService EquipmentSvc
@inject PersistentComponentState ApplicationState

<PageTitle>Inventory</PageTitle>

<h1>Equipment Inventory</h1>

@if (_items is null)
{
    <p><em>Loading inventory...</em></p>
}
else
{
    <table class="table">
        <thead>
            <tr>
                <th>Id</th>
                <th>Name</th>
                <th>Location</th>
                <th>Last Inspected</th>
            </tr>
        </thead>
        <tbody>
            @foreach (var item in _items)
            {
                <tr>
                    <td>@item.Id</td>
                    <td>@item.Name</td>
                    <td>@item.Location</td>
                    <td>@item.LastInspected.ToShortDateString()</td>
                </tr>
            }
        </tbody>
    </table>
}

@code {
    private List<EquipmentItem>? _items;
    private PersistingComponentStateSubscription _persistingSubscription;

    protected override async Task OnInitializedAsync()
    {
        _persistingSubscription = ApplicationState.RegisterOnPersisting(PersistData);

        // If the data was already persisted during prerender, reuse it
        // instead of calling the service a second time.
        if (ApplicationState.TryTakeFromJson<List<EquipmentItem>>("inventory", out var restored))
        {
            _items = restored;
        }
        else
        {
            _items = await EquipmentSvc.GetEquipmentAsync();
        }
    }

    private Task PersistData()
    {
        ApplicationState.PersistAsJson("inventory", _items);
        return Task.CompletedTask;
    }

    public void Dispose()
    {
        _persistingSubscription.Dispose();
    }
}

